Writing the error boundary component now.

**src/components/ErrorBoundary.tsx**

```tsx
import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary]", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
      timestamp: new Date().toISOString(),
    });
  }

  retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.retry);

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.title}>Something went wrong</h2>
        <pre style={styles.message}>{error.message}</pre>
        <button onClick={this.retry} style={styles.button}>
          Try again
        </button>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "2rem",
    gap: "1rem",
    fontFamily: "sans-serif",
  },
  title: { margin: 0, color: "#c0392b" },
  message: {
    background: "#f8f8f8",
    border: "1px solid #ddd",
    borderRadius: "4px",
    padding: "0.75rem 1rem",
    maxWidth: "100%",
    overflowX: "auto",
    fontSize: "0.875rem",
  },
  button: {
    padding: "0.5rem 1.25rem",
    background: "#2563eb",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "1rem",
  },
};
```

**Usage**

```tsx
// Basic — uses built-in fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, retry) => (
    <div>
      <p>{error.message}</p>
      <button onClick={retry}>Retry</button>
    </div>
  )}
>
  <MyComponent />
</ErrorBoundary>
```

Key decisions:

- **Class component** — required; `getDerivedStateFromError` / `componentDidCatch` have no hook equivalents.
- **`retry`** resets state to `null`, which unmounts the error UI and re-renders children fresh.
- **`fallback` prop** accepts `(error, retry) => ReactNode` so callers control the UI without forking the boundary.
- **`componentDidCatch`** logs a structured object (message, stack, component stack, timestamp) — swap the `console.error` call for your real logger (Sentry, Datadog, etc.).
- **`role="alert"`** on the default fallback ensures screen readers announce the error.
